  const payExact = async p => { await p.click('[data-pay="cash"]'); await p.click('#rGo'); await p.click('[data-v="exact"]'); await p.click('#pOk'); await p.click('#cYes'); await p.click('#apOk'); await p.waitForTimeout(100); };
